/// Captures the Game View after rendering one normal production frame when needed.
///
/// Managed AI observations can therefore use the same runtime renderer even when the visible
/// Editor is not currently painting the Game View panel.
pub fn capture_or_render_game_view(
    &mut self,
    render_state: &egui_wgpu::RenderState,
    fallback_size: [u32; 2],
) -> Result<FrameCapture, GameViewError> {
    if self.game_view.is_none() {
        self.render_game_view(render_state, fallback_size)?;
    }
    self.capture_game_view(render_state)
}

